export async function buildPilot(store,actor,pilot,{inspect=null}={}){
 const source=await importDocument(store,actor,{filename:`${pilot.id}.md`,role:'technical',title:`Dossier ${pilot.title}`},Buffer.from(pilot.source));
 const config=qualityConfig({EDEN_AI_MODEL:'gpt-6.1-sol',EDEN_AI_MAX_SESSION_MINUTES:'90'});
 let job=await enqueueGeneration(store,actor,{intent:`Pilote ${pilot.title}`,entryId:pilot.id,sourceIds:[source.id],requestId:`fixture-${pilot.id}`},{config,simulation:true});if(!['queued','running'].includes(job.status))return job;
 if(job.stage==='assemble'){await runGenerationStep(store,{call:fixtureResponder(pilot),inspect});job=await store.get('generation_jobs',job.id);job.capabilities=fixtureCapabilities();job.referenceBaseline=structuredClone(job.baseline);job.workingSpec=pilotSpec(pilot,job.workingSpec);job.baseline=structuredClone(job.workingSpec);await store.put('generation_jobs',job);}
 for(let i=0;i<25;i++){job=await store.get('generation_jobs',job.id);if(!['queued','running'].includes(job.status))break;await runGenerationStep(store,{call:fixtureResponder(pilot),inspect});}
 return store.get('generation_jobs',job.id);
}
